      cx += sX * exactDist;
      cy += sY * exactDist;
      if (Math.abs(cx - piece.x) > Math.max(boardWidth, boardHeight) + 2 || Math.abs(cy - piece.y) > Math.max(boardWidth, boardHeight) + 2) break;
