  invalidateLobbyCache,
  // Option A move-history storage
  loadGameMoves,
  saveGameMoves,
  // Pure game logic functions (used by AI engine)
  getPossibleMovesForPiece,
  getAllLegalMovesForPlayer,
  checkForCheck,
  isCheckmate,
  checkWinCondition,
  validateAndApplyMove,
  wouldMoveLeaveInCheck,
  findPieceAtSquare,
  doesPieceOccupySquare,
  canRangedAttackTo,
  isRangedPathClear,
  // Veto power (used by AI engine to respect opponent bans)
  vetoSignature,
  getVetoConfig,
  getValidFlankingPlacements,
  applyFlankingCaptures,
  // Surround (enclosure) capture + scoring
  resolveSurroundCaptures,
